  data = $fdirjson${"slug": "directing", "title": "Directing", "description": "Directing begins with point of view: the ability to interpret material, lead collaborators, and make choices that serve story, audience, and production reality.", "topics": [{"id": "3edba54e-f56c-4c27-8377-e1134fa23f61", "type": "topic", "title": "The Director's Role, Vision, Voice, and Ethical Responsibility", "description": "Directing begins with point of view: the ability to interpret material, lead collaborators, and make choices that serve story, audience, and production reality.", "children": [{"id": "389b96d3-ed58-4b4c-9584-9d587ceb2413", "type": "subtopic", "title": "Director as interpreter and author", "children": [{"id": "660265a0-0664-485d-90ab-28c817dd019e", "type": "concept", "title": "Interpretive thesis"}, {"id": "54ce5c46-59f1-49ff-9e2d-ef4679e54cc7", "type": "concept", "title": "Personal voice"}, {"id": "4005478c-f619-45f5-8e87-6d944cb09448", "type": "concept", "title": "Audience contract"}, {"id": "3d91088b-e643-49b0-9c71-59a4d69c922f", "type": "concept", "title": "Genre and tone"}], "description": "Students learn how a director turns a script or concept into a specific cinematic or theatrical experience."}, {"id": "39f237d5-b64e-4ca8-89ca-457ac365b137", "type": "subtopic", "title": "Leadership and responsibility", "children": [{"id": "46f5589f-d227-4b15-8be0-76297cc7a140", "type": "concept", "title": "Creative decision-making"}, {"id": "2488b6af-a66d-4745-9583-e8992c92d6dc", "type": "concept", "title": "Crew morale"}, {"id": "cea0c805-f0d1-4f22-bee8-5130359d2db9", "type": "concept", "title": "Power dynamics"}, {"id": "ad1e6f28-04d7-4e88-9854-a7bf96c2236b", "type": "concept", "title": "Inclusive leadership"}], "description": "The director's authority is studied as a service role grounded in clarity, respect, and preparation."}, {"id": "334ed548-13c9-4e4b-8d0e-aeed72195fcc", "type": "subtopic", "title": "Ethical storytelling", "children": [{"id": "dca1a9e8-f4f2-4c88-8ff0-