roduction design"}, {"id": "cc250187-2e95-41a3-ae5f-c2500e4d6d36", "type": "concept", "title": "Costume palette"}, {"id": "2048b7c4-39f8-4f7a-a091-b9bb52eb20a3", "type": "concept", "title": "Props as action"}, {"id": "dd29e3ed-0fe3-4c41-af39-9d4c8dfcddfb", "type": "concept", "title": "Period and world logic"}], "description": "This subtopic covers how space, props, costume, makeup, and color shape story and character."}, {"id": "71812d13-dee2-4543-b220-0d91dbfd29ca", "type": "subtopic", "title": "Sound and editorial collaboration", "children": [{"id": "cd895f85-e5c0-43b3-9eb6-1af415999512", "type": "concept", "title": "Sound motifs"}, {"id": "80043b8c-ee8d-44ab-b134-b394f012b823", "type": "concept", "title": "Edit points"}, {"id": "d5f56dae-d4f2-48a8-a72b-96d733925479", "type": "concept", "title": "Room tone"}, {"id": "91355475-55e1-49fa-aafb-f2190c0b5bad", "type": "concept", "title": "Post conversations"}], "description": "Students think about sound and editing before shooting so coverage supports the final experience."}]}, {"id": "63214289-9b1f-493e-b8a3-a78dbd97e06f", "type": "topic", "title": "Pre-Production, Scheduling, Budget Awareness, and Production Planning", "description": "Creative freedom depends on preparation: directors need enough production literacy to make strong choices inside real constraints.", "children": [{"id": "da2b8662-3571-4c5a-9ce1-e74929e6070b", "type": "subtopic", "title": "Breakdowns and feasibility", "children": [{"id": "a45f4fb7-9059-45cf-a663-d3f4ff018157", "type": "concept", "title": "Scene breakdown"}, {"id": "b45197f0-5301-4b64-b5e3-5a89c093122a", "type": "concept", "title": "Location needs"}, {"id": "a85747c5-b1e8-48e4-8ecd-de0580a52d42", "type": "concept", "title": "Company moves"}, {"id": "3d1ece5b-de43-4416-a408-9b79dac41e34", "type": "concept", "title": "Special requirements"}], "description": "Students learn to read scripts for locations, cast, props, effects, time, risk, and cost."}, {"id": "3867aa05-7ca8-4f7f-a7e1-5a318c5e